import type { ContentBlockManifestEntry } from './contentBlocks.js'

// Hand-authored, NOT generated by scripts/scanVariables.mjs. Page 10 is a legal Service
// Agreement — 99% static, and the legal wording must never be editable. Only the two
// signature VALUES ("[Company Name]" / "[Client Name]") are in scope here; they're each a
// sole bracket placeholder, which the scanner already deliberately excludes (see
// contentBlocks.generated.ts's own header comment), so this fills that one real gap. The
// legal body text and the left-side "Novara Consult"/"Jayson Kandiah" signature ARE already
// scanner-generated content blocks today — see ProposalEditor.tsx, which deliberately does
// NOT include page10's generated blocks in its entries at all, so none of that text ever
// receives a data-editor-key or becomes clickable.

export interface Page10FieldSource {
  companyName?: string
  clientName?: string
}

export function getPage10FieldEntries(source: Page10FieldSource): ContentBlockManifestEntry[] {
  return [
    {
      key: 'page10.companyName',
      page: 'page10',
      originalText: source.companyName?.trim() || '[Company Name]',
      label: 'Company Name',
      variants: ['both'],
    },
    {
      key: 'page10.clientName',
      page: 'page10',
      originalText: source.clientName?.trim() || '[Client Name]',
      label: 'Client Name',
      variants: ['both'],
    },
  ]
}
